import java.util.Scanner;

public class Main {
    public static double getAbs(double val) {
        return (val < 0) ? -val : val;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int x = sc.nextInt();
        int y = sc.nextInt();
        int n = sc.nextInt();

        int numerator = 0;
        int denominator = 1;
        double minimalDifference = 1e15;
        double targetRatio = (double) x / y;

        for (int j = 1; j <= n; ++j) {
            int low = 0;
            int high = 1000000000;
            while (high - low > 10) {
                int mid1 = low + (high - low) / 3;
                int mid2 = high - (high - low) / 3;
                double diff1 = getAbs(targetRatio - (double) mid1 / j);
                double diff2 = getAbs(targetRatio - (double) mid2 / j);
                if (diff1 > diff2)
                    low = mid1;
                else
                    high = mid2;
            }
            for (int i = low; i <= high + 3; ++i) {
                double currentDiff = getAbs(targetRatio - (double) i / j);
                if (currentDiff < minimalDifference - 1e-15) {
                    minimalDifference = currentDiff;
                    numerator = i;
                    denominator = j;
                }
            }
        }
        System.out.println(numerator + "/" + denominator);
        sc.close();
    }
}
